#!/usr/bin/env php
<?php
declare(strict_types=1);
require dirname(__DIR__).'/src/bootstrap.php';$root=dirname(__DIR__);$config=Config::load($root);$pdo=Database::connect($config['db_path']);Database::migrate($pdo,$root.'/sql/schema.sql');$s=$pdo->prepare('SELECT id FROM characters WHERE lower(name)=lower(:n) ORDER BY id LIMIT 1');$s->execute([':n'=>$config['character']]);$cid=(int)$s->fetchColumn();if(!$cid){fwrite(STDERR,"Character not imported yet.\n");exit(2);} $d=(new SnapshotDiffer($pdo,$cid))->latest();if(!$d['available']){echo "Need at least two GearFinder snapshots for a diff.\n";exit(0);}printf("Current %s vs previous %s\n",$d['current']['captured_at'],$d['previous']['captured_at']);foreach(['added','removed','moved','augment_changed'] as $k)printf("%-16s %d\n",$k,count($d[$k]));foreach($d['added'] as $r)printf("+ %dx %s\n",$r['delta'],$r['name']);foreach($d['removed'] as $r)printf("- %dx %s\n",$r['delta'],$r['name']);foreach($d['moved'] as $r)printf("~ %s %s -> %s\n",$r['item']['name'],implode(',',$r['from']),implode(',',$r['to']));foreach($d['augment_changed'] as $r)printf("* %s augment signature changed at %s/%s\n",$r['after']['name'],$r['after']['bag_name'],$r['after']['bag_slot']);
